45	  /** SFCC variation-attribute value, e.g. "BAYBL" — the identity matched against `selectedValue`. */
46	  value: string;
47	  /** Colour display name, e.g. "Bay Blue". Rendered as the dynamic label text and, via the atom, each swatch's accessible name. */
48	  name: string;
49	  /** Destination URL for this colour. Absent for the quick-view-modal path — see ZimmColourSwatch. */
50	  href?: string;
51	  /**
52	   * Fully resolved swatch-fill image URL. Undefined means this colour's index image is not
53	   * populated (AC 5) — such a value is filtered out before rendering and never surfaced to the
54	   * shopper, regardless of any stock/orderability field it might otherwise carry.
55	   */
56	  imageUrl?: string;
57	};
58	
59	/** A colour value that has passed the AC-5 image-populated filter below. */
60	type PopulatedSwatchValue = ZimmColourSwatchValue & { imageUrl: string };
61	
62	type ZimmColourSwatchGroupProps = {
63	  /**
64	   * SFCC attribute display name, e.g. "Colour" — interpolated into the "{label}:" text and used
65	   * as the swatches `radiogroup`'s aria-label.
66	   */
67	  label: string;
68	  /** Display name of the currently selected colour, e.g. "Bay Blue". */
69	  selectedName?: string;
70	  /** SFCC variation-attribute value of the currently selected colour, e.g. "BAYBL". */
71	  selectedValue?: string;
72	  /** Every selectable colour value for this attribute, populated or not — this component performs its own AC-5 filter. */
73	  values: readonly ZimmColourSwatchValue[];
