78	 * more than one populated colour — the row of clickable colour swatches beneath it.
79	 *
80	 * Purely presentational — no data-fetching hook of any kind. SFCC data resolution (building
81	 * `imageUrl`/`href` from a product's variation attributes) happens at the page level, not here.
82	 *
83	 * Three ACs live here as branch logic:
84	 *   - AC 5: a colour whose index image is not populated is filtered out before rendering and
85	 *     never surfaced to the shopper. Content-population, not stock/orderability — the filter
86	 *     keys on `imageUrl` alone.
87	 *   - AC 1: filtering *then* counting means an unpopulated colour never counts toward "there are
88	 *     multiple colours" — one populated colour (or zero) renders the label row only, with no
89	 *     `swatches` node and no `radiogroup` role at all.
90	 *   - Pagination: more than 4 populated colours paginates in fixed 4-wide windows. Paging moves
91	 *     the window only, never the selection — a selected colour that pages out of view stays
92	 *     selected, it is just not visible until paged back into view.
93	 *
94	 * @param props see ZimmColourSwatchGroupProps
95	 */
96	export const ZimmColourSwatchGroup = ({ label, selectedName, selectedValue, values }: ZimmColourSwatchGroupProps) => {
97	  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCH_GROUP_RECIPE, {});
98	  const intl = useIntl();
99	  const swatchesRef = useRef<HTMLDivElement>(null);
100	  const [pageStart, setPageStart] = useState(0);
