102	  // AC 5. Lives here, not at the page level, because this component's own test file is where its
103	  // contract must be provable — the PDP page has no test file of its own. A type predicate
104	  // rather than a `!` at the call site below: TypeScript then knows every entry of `populated`
105	  // genuinely carries a string `imageUrl`, with no unchecked assertion needed.
106	  const populated = values.filter((value): value is PopulatedSwatchValue => Boolean(value.imageUrl));
107	
108	  const isPaginated = populated.length > SWATCHES_PER_PAGE;
109	  // Defensive clamp, not part of any AC: if `values` shrinks while this instance stays mounted
110	  // (no remount), a stale `pageStart` left over from a longer list would otherwise slice to an
111	  // empty window with no swatches rendered at all.
112	  const lastPageStart = Math.max(0, Math.ceil(populated.length / SWATCHES_PER_PAGE) - 1) * SWATCHES_PER_PAGE;
113	  const currentPageStart = Math.min(pageStart, lastPageStart);
114	  const windowed = isPaginated ? populated.slice(currentPageStart, currentPageStart + SWATCHES_PER_PAGE) : populated;
115	  const canGoBack = currentPageStart > 0;
116	  const canGoForward = currentPageStart + SWATCHES_PER_PAGE < populated.length;
117	
118	  const handlePrevPage = () => setPageStart((current) => Math.max(0, current - SWATCHES_PER_PAGE));
119	  const handleNextPage = () => setPageStart((current) => Math.min(current + SWATCHES_PER_PAGE, lastPageStart));
120	
121	  /*
122	   * Roving focus across the *rendered* swatches, mirroring base SFCC's own
123	   * swatch-group/index.jsx onKeyDown (ArrowUp/ArrowLeft = backward, ArrowDown/ArrowRight =
124	   * forward, wrapping at the ends via modulus). Deliberately moves DOM focus only, via
125	   * `.focus()` on the sibling node, rather than touching `isFocusable`/selection state the way
126	   * base's own version does: there is no onVariationChange-equivalent prop here for an arrow
127	   * press to call (product-detail, Step 4, passes none yet), so there is nothing to trigger
128	   * beyond moving which element has focus. Activation stays the anchor's native Enter key,
129	   * inherited for free from the atom's ColourSwatchLink. Space does not activate an anchor
130	   * element — a native browser/HTML behaviour, not a bug, and an inherited parity gap versus a
131	   * true native radio input rather than a new regression introduced here.
132	   */
133	  const handleSwatchesKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
134	    const { key } = event;
135	    if (key !== 'ArrowUp' && key !== 'ArrowDown' && key !== 'ArrowLeft' && key !== 'ArrowRight') return;
136	    event.preventDefault();
137	    const container = swatchesRef.current;
138	    if (!container) return;
139	    const items = Array.from(container.children) as HTMLElement[];
140	    if (items.length === 0) return;
141	    const direction = key === 'ArrowUp' || key === 'ArrowLeft' ? -1 : 1;
142	    const activeIndex = items.indexOf(document.activeElement as HTMLElement);
143	    const fromIndex = activeIndex === -1 ? 0 : activeIndex;
144	    const nextIndex = (fromIndex + direction + items.length) % items.length;
145	    items[nextIndex]?.focus();
146	  };
147	
148	  return (
149	    <chakra.div __css={styles.root} data-testid="colour-swatch-group">
150	      <chakra.div __css={styles.label}>
151	        {/*
152	          The label-group (the two "Colour:"/name text pieces) has no dedicated recipe part —
153	          only `labelName`, the piece that actually truncates, does. This wrapper's layout (flex
154	          row, 4px internal gap, flex: 1 0 0 so the pagination controls are pushed to the right)
155	          is expressed as direct Chakra props with var(--zimm-*) values instead, per
156	          overrideStyling.md's "your call" allowance for this one sub-piece.
157	        */}
158	        <chakra.div display="flex" alignItems="center" gap="var(--zimm-scale-2xs)" flex="1 0 0" minWidth={0}>
159	          <chakra.span textStyle="caption" color="var(--zimm-color-text-default)" flexShrink={0}>
160	            {intl.formatMessage(GROUP_LABEL_MESSAGE, { label })}
161	          </chakra.span>{' '}
162	          <chakra.span __css={styles.labelName}>{selectedName}</chakra.span>
163	        </chakra.div>
164	
165	        {isPaginated && (
166	          <chakra.div __css={styles.pagination}>
167	            <chakra.button
168	              type="button"
169	              __css={styles.pageButton}
170	              onClick={handlePrevPage}
171	              disabled={!canGoBack}
172	              aria-label={intl.formatMessage(PREVIOUS_PAGE_MESSAGE)}
173	            >
174	              <ZimmIcon type="chevron-left" size="md" aria-hidden={true} />
175	            </chakra.button>
176	            <chakra.button
177	              type="button"
178	              __css={styles.pageButton}
179	              onClick={handleNextPage}
180	              disabled={!canGoForward}
181	              aria-label={intl.formatMessage(NEXT_PAGE_MESSAGE)}
182	            >
183	              <ZimmIcon type="chevron-right" size="md" aria-hidden={true} />
184	            </chakra.button>
185	          </chakra.div>
186	        )}
187	      </chakra.div>
188	
189	      {populated.length > 1 && (
190	        <chakra.div
191	          __css={styles.swatches}
192	          ref={swatchesRef}
193	          role="radiogroup"
194	          aria-label={label}
195	          onKeyDown={handleSwatchesKeyDown}
196	        >
197	          {windowed.map((value, index) => {
198	            const isSelected = value.value === selectedValue;
199	            // Base SFCC's own exact roving-tabindex rule (product-view/index.tsx's
200	            // renderDefaultVariationAttribute) — applied over the rendered *window*, since only
201	            // a rendered element can ever be a real focus target.
202	            const isFocusable = isSelected || (!selectedValue && index === 0);
203	            return (
204	              <ZimmColourSwatch
205	                key={value.value}
206	                name={value.name}
207	                imageUrl={value.imageUrl}
208	                href={value.href}
209	                isSelected={isSelected}
210	                isFocusable={isFocusable}
