68	  /** Display name of the currently selected colour, e.g. "Bay Blue". */
69	  selectedName?: string;
70	  /** SFCC variation-attribute value of the currently selected colour, e.g. "BAYBL". */
71	  selectedValue?: string;
72	  /** Every selectable colour value for this attribute, populated or not — this component performs its own AC-5 filter. */
73	  values: readonly ZimmColourSwatchValue[];
74	};
75	
76	/**
77	 * Molecule — the PDP colour-swatch group: the "Colour: Bay Blue" label row, and — once there is
78	 * more than one populated colour — the row of clickable colour swatches beneath it.
79	 *
80	 * Purely presentational — no data-fetching hook of any kind. SFCC data resolution (building
81	 * `imageUrl`/`href` from a product's variation attributes) happens at the page level, not here.
82	 *
83	 * Three ACs live here as branch logic:
84	 *   - AC 5: a colour whose index image is not populated is filtered out before rendering and
85	 *     never surfaced to the shopper. Content-population, not stock/orderability — the filter
86	 *     keys on `imageUrl` alone.
87	 *   - AC 1: filtering *then* counting means an unpopulated colour never counts toward "there are
88	 *     multiple colours" — one populated colour (or zero) renders the label row only, with no
89	 *     `swatches` node and no `radiogroup` role at all.
90	 *   - Pagination: more than 4 populated colours paginates in fixed 4-wide windows. Paging moves
91	 *     the window only, never the selection — a selected colour that pages out of view stays
92	 *     selected, it is just not visible until paged back into view.
93	 *
94	 * @param props see ZimmColourSwatchGroupProps
95	 */
96	export const ZimmColourSwatchGroup = ({ label, selectedName, selectedValue, values }: ZimmColourSwatchGroupProps) => {
97	  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCH_GROUP_RECIPE, {});
98	  const intl = useIntl();
99	  const swatchesRef = useRef<HTMLDivElement>(null);
100	
101	  // AC 5. Lives here, not at the page level, because this component's own test file is where its
102	  // contract must be provable — the PDP page has no test file of its own. A type predicate
103	  // rather than a `!` at the call site below: TypeScript then knows every entry of `populated`
104	  // genuinely carries a string `imageUrl`, with no unchecked assertion needed.
105	  const populated = values.filter((value): value is PopulatedSwatchValue => Boolean(value.imageUrl));
106	
107	  // The page that actually contains the current selection, recomputed fresh every render from
108	  // `populated`/`selectedValue` — never a second, independently-drifting copy of "where the
109	  // selection is." -1 (no match, or nothing selected yet) falls back to page 1, matching the
110	  // existing no-selection behaviour.
111	  const selectedIndex = populated.findIndex((value) => value.value === selectedValue);
112	  const selectedPageStart =
113	    selectedIndex === -1 ? 0 : Math.floor(selectedIndex / SWATCHES_PER_PAGE) * SWATCHES_PER_PAGE;
114	
115	  // Seeded from `selectedPageStart` so the very first render already lands on the selection's
116	  // real page — React only consumes this argument on mount, so this alone covers first render.
117	  // It is not enough on its own once mounted: if `selectedValue`/`populated` change afterwards,
118	  // this initial value would go stale, because `pageStart` gates which items are even rendered,
119	  // not just which one shows a highlight — unlike base SFCC's own per-render-derived
120	  // `isFocusable`, which only ever affects a highlight on whatever is already on screen. The
121	  // effect below is what keeps `pageStart` correct for the lifetime of an already-mounted
122	  // instance.
123	  const [pageStart, setPageStart] = useState(selectedPageStart);
124	
125	  // Resyncs `pageStart` to the selection's own page whenever `selectedPageStart` itself changes —
126	  // i.e. whenever a `selectedValue`/`populated` prop update moves the selection to a different
127	  // page on an already-mounted instance. Manual prev/next clicks (handlePrevPage/handleNextPage
128	  // below) only ever set `pageStart` directly and never touch `selectedPageStart`, so this effect
129	  // does not re-run on a manual page click and manual paging keeps working exactly as before in
130	  // between selection changes.
131	  useEffect(() => {
132	    setPageStart(selectedPageStart);
133	  }, [selectedPageStart]);
134	
135	  const isPaginated = populated.length > SWATCHES_PER_PAGE;
136	  // Defensive clamp, not part of any AC: if `values` shrinks while this instance stays mounted
137	  // (no remount), a stale `pageStart` left over from a longer list would otherwise slice to an
138	  // empty window with no swatches rendered at all.
139	  const lastPageStart = Math.max(0, Math.ceil(populated.length / SWATCHES_PER_PAGE) - 1) * SWATCHES_PER_PAGE;
140	  const currentPageStart = Math.min(pageStart, lastPageStart);
141	  const windowed = isPaginated ? populated.slice(currentPageStart, currentPageStart + SWATCHES_PER_PAGE) : populated;
142	  const canGoBack = currentPageStart > 0;
143	  const canGoForward = currentPageStart + SWATCHES_PER_PAGE < populated.length;
144	
145	  const handlePrevPage = () => setPageStart((current) => Math.max(0, current - SWATCHES_PER_PAGE));
146	  const handleNextPage = () => setPageStart((current) => Math.min(current + SWATCHES_PER_PAGE, lastPageStart));
147	
148	  /*
149	   * Roving focus across the *rendered* swatches, mirroring base SFCC's own
150	   * swatch-group/index.jsx onKeyDown (ArrowUp/ArrowLeft = backward, ArrowDown/ArrowRight =
151	   * forward, wrapping at the ends via modulus). Deliberately moves DOM focus only, via
152	   * `.focus()` on the sibling node, rather than touching `isFocusable`/selection state the way
153	   * base's own version does: there is no onVariationChange-equivalent prop here for an arrow
154	   * press to call (product-detail, Step 4, passes none yet), so there is nothing to trigger
155	   * beyond moving which element has focus. Activation stays the anchor's native Enter key,
156	   * inherited for free from the atom's ColourSwatchLink. Space does not activate an anchor
157	   * element — a native browser/HTML behaviour, not a bug, and an inherited parity gap versus a
158	   * true native radio input rather than a new regression introduced here.
159	   */
160	  const handleSwatchesKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
161	    const { key } = event;
162	    if (key !== 'ArrowUp' && key !== 'ArrowDown' && key !== 'ArrowLeft' && key !== 'ArrowRight') return;
163	    event.preventDefault();
164	    const container = swatchesRef.current;
165	    if (!container) return;
166	    const items = Array.from(container.children) as HTMLElement[];
167	    if (items.length === 0) return;
168	    const direction = key === 'ArrowUp' || key === 'ArrowLeft' ? -1 : 1;
169	    const activeIndex = items.indexOf(document.activeElement as HTMLElement);
170	    const fromIndex = activeIndex === -1 ? 0 : activeIndex;
171	    const nextIndex = (fromIndex + direction + items.length) % items.length;
172	    items[nextIndex]?.focus();
173	  };
174	
175	  return (
176	    <chakra.div __css={styles.root} data-testid="colour-swatch-group">
177	      <chakra.div __css={styles.label}>
178	        {/*
179	          The label-group (the two "Colour:"/name text pieces) has no dedicated recipe part —
180	          only `labelName`, the piece that actually truncates, does. This wrapper's layout (flex
181	          row, 4px internal gap, flex: 1 0 0 so the pagination controls are pushed to the right)
182	          is expressed as direct Chakra props with var(--zimm-*) values instead: it is a
183	          structural, one-off layout wrapper with no competing or interactive style definitions of
184	          its own, so overrideStyling.md's "one canonical styling surface per component type" rule
185	          — scoped to components with competing/interactive style definitions — does not clearly
186	          apply here, and a dedicated recipe part would only exist to hold a single fixed flex-row
187	          layout that nothing else varies.
188	        */}
189	        <chakra.div display="flex" alignItems="center" gap="var(--zimm-scale-2xs)" flex="1 0 0" minWidth={0}>
190	          <chakra.span textStyle="caption" color="var(--zimm-color-text-default)" flexShrink={0}>
191	            {intl.formatMessage(GROUP_LABEL_MESSAGE, { label })}
192	          </chakra.span>{' '}
193	          <chakra.span __css={styles.labelName}>{selectedName}</chakra.span>
194	        </chakra.div>
195	
196	        {isPaginated && (
197	          <chakra.div __css={styles.pagination}>
198	            <chakra.button
199	              type="button"
200	              __css={styles.pageButton}
201	              onClick={handlePrevPage}
202	              disabled={!canGoBack}
203	              aria-label={intl.formatMessage(PREVIOUS_PAGE_MESSAGE)}
204	            >
205	              <ZimmIcon type="chevron-left" size="md" aria-hidden={true} />
206	            </chakra.button>
207	            <chakra.button
208	              type="button"
209	              __css={styles.pageButton}
210	              onClick={handleNextPage}
211	              disabled={!canGoForward}
212	              aria-label={intl.formatMessage(NEXT_PAGE_MESSAGE)}
213	            >
214	              <ZimmIcon type="chevron-right" size="md" aria-hidden={true} />
215	            </chakra.button>
216	          </chakra.div>
217	        )}
218	      </chakra.div>
219	
220	      {populated.length > 1 && (
221	        <chakra.div
222	          __css={styles.swatches}
223	          ref={swatchesRef}
224	          role="radiogroup"
225	          aria-label={label}
226	          onKeyDown={handleSwatchesKeyDown}
227	        >
228	          {windowed.map((value, index) => {
229	            const isSelected = value.value === selectedValue;
230	            // Base SFCC's own exact roving-tabindex rule (product-view/index.tsx's
231	            // renderDefaultVariationAttribute) — applied over the rendered *window*, since only
232	            // a rendered element can ever be a real focus target.
233	            const isFocusable = isSelected || (!selectedValue && index === 0);
234	            return (
235	              <ZimmColourSwatch
236	                key={value.value}
237	                name={value.name}
238	                imageUrl={value.imageUrl}
239	                href={value.href}
240	                isSelected={isSelected}
241	                isFocusable={isFocusable}
242	              />
243	            );
244	          })}
245	        </chakra.div>
246	      )}
247	    </chakra.div>
248	  );
249	};
